import{c as o,Z as e,Q as i,j as l,m as r,o as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"凉州词","description":"","frontmatter":{"title":"凉州词","author":"王之涣","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/11.md","filePath":"books/shici/tangshi/11.md"}'),h={name:"books/shici/tangshi/11.md"};function s(u,a,c,p,d,q){const t=e("PoemNav");return i(),l("div",null,[a[0]||(a[0]=r('<h1 id="凉州词" tabindex="-1">凉州词 <a class="header-anchor" href="#凉州词" aria-label="Permalink to &quot;凉州词&quot;">​</a></h1><p><strong>[唐] <a href="/authors/wangzhihuan.html">王之涣</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>黄河远上白云间，一片孤城万仞山。 羌笛何须怨杨柳，春风不度玉门关。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>凉州词：唐代乐府曲名，多写边塞风光和军旅生活</li><li>黄河远上：一作&quot;黄沙直上&quot;，形容黄河源远流长，直上云端</li><li>白云间：形容黄河源头高远，仿佛流入白云之中</li><li>孤城：指玉门关，在今甘肃省敦煌市西北</li><li>万仞山：形容山势极高，仞是古代长度单位</li><li>羌笛：古代羌族的一种乐器</li><li>杨柳：指《折杨柳》曲，乐府横吹曲名，古人送别时吹奏</li><li>怨杨柳：吹奏《折杨柳》曲表达离别之怨</li><li>度：吹过</li><li>玉门关：汉代设置的边关，是古代通往西域的要道</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>黄河源远流长，仿佛直上白云之间。一座孤城矗立在万仞高山之中。羌笛何必吹奏《折杨柳》来哀怨离别呢，春风是吹不过玉门关的。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是王之涣的边塞诗代表作，描写了边塞的苍凉景象和戍边将士的思乡之情，是唐人绝句中的精品。</p><p>首句&quot;黄河远上白云间&quot;，写黄河的源远流长。诗人以夸张的手法，将黄河写得仿佛从白云间奔流而下，既写出了黄河的雄伟气势，又暗示了边塞的遥远和荒凉。</p><p>次句&quot;一片孤城万仞山&quot;，写玉门关的孤危地势。&quot;一片孤城&quot;与&quot;万仞山&quot;形成鲜明对比，突出了边塞城池的孤独和险要，也暗示了戍边将士的艰苦生活。</p><p>后两句&quot;羌笛何须怨杨柳，春风不度玉门关&quot;，是全诗的精华所在。诗人以羌笛吹奏《折杨柳》曲起兴，写戍边将士的思乡之情。&quot;春风不度玉门关&quot;一句，既写出了边塞的荒凉寒冷，又暗示了朝廷的恩泽不及边塞，含蓄地表达了对戍边将士的同情。</p><p>全诗意境雄浑，语言凝练，将边塞的苍凉、将士的思乡和对朝廷的委婉批评融为一体，是盛唐边塞诗的代表作。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>王之涣</strong>（688年－742年），字季凌，唐代著名诗人，以描写边疆风光著称。其诗气势雄浑，意境开阔，可惜作品多已散佚，传世仅六首。</p><p><a href="/authors/wangzhihuan.html">查看作者详情 →</a></p></blockquote>',17)),n(t)])}const b=o(h,[["render",s]]);export{m as __pageData,b as default};
